726		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
727			entry(1, 1, "set balance=100"),
728			entry(2, 2, "set balance=200"),
729		}}
730		original := append([]LogEntry(nil), initial.Log...)
731		cases := []struct {
732			name    string
733			request AppendRequest
734		}{
735			{
736				// 任务主场景：任期 7、前置 idx2/任期2 与本地一致，首条 idx3 任期 1
737				// 低于声明的前置任期 2；leaderCommit 再大也无济于事。
738				"matching prev, higher term, huge leaderCommit",
739				AppendRequest{Term: 7, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 9,
740					Entries: []LogEntry{entry(3, 1, "x")}},
741			},
742			{
743				// 声明的前置任期与本地日志不一致（本地 idx2 任期 2，声明 5），但
744				// 首条任期 1 仍低于声明值：仍是同一条字段错误，不能改成前置日志
745				// 不匹配，也不能留下较高任期更新。
746				"declared prev term mismatches local too",
747				AppendRequest{Term: 7, PrevLogIndex: 2, PrevLogTerm: 5, LeaderCommit: 9,
748					Entries: []LogEntry{entry(3, 1, "x")}},
749			},
750			{
751				// 前置索引越过本地日志末尾，首条索引随之合法地落在日志之后：衔接
752				// 错误仍先于前缀核对，不附带重发建议。
753				"prev index beyond log",
754				AppendRequest{Term: 8, PrevLogIndex: 5, PrevLogTerm: 3, LeaderCommit: 0,
755					Entries: []LogEntry{entry(6, 2, "x")}},
756			},
757			{
758				// 首条任期等于……严格低于才非法：这里首条比前置任期低 1，且声明
759				// 前置任期与本地不同，字段错误判定只看声明值。
760				"first term one below declared prev term",
761				AppendRequest{Term: 7, PrevLogIndex: 2, PrevLogTerm: 3, LeaderCommit: 4,
762					Entries: []LogEntry{entry(3, 2, "x")}},
763			},
764			{
765				// 多条目自身任期不下降（1 -> 7），但首条低于前置任期 2：条目内部
766				// 规则通过，衔接规则单独拒绝；第二条的高任期同样不能留下更新。
767				"multiple entries internally non-decreasing but bridge too low",
768				AppendRequest{Term: 7, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 4,
769					Entries: []LogEntry{entry(3, 1, "x"), entry(4, 7, "y")}},
770			},
771		}
772		for _, tc := range cases {
773			t.Run(tc.name, func(t *testing.T) {
774				out := run(t, initial, tc.request)
775				result := out.Results[0]
776				if result.Accepted {
777					t.Fatalf("request should be rejected: %+v", result)
778				}
779				if result.Reason != ReasonEntryTermDecreases {
780					t.Fatalf("reason = %q, want exact %q", result.Reason, ReasonEntryTermDecreases)
781				}
782				if !strings.Contains(result.Reason, "entry terms are not non-decreasing") {
783					t.Fatalf("reason text changed: %q", result.Reason)
784				}
785				if result.Conflict != nil {
786					t.Fatalf("field error must not be treated as a replication conflict: %+v", result.Conflict)
787				}
788				if result.Term != 2 {
789					t.Fatalf("higher term must not survive a field error, term = %d, want 2", result.Term)
790				}
791				if result.CommittedIndex != 1 {
792					t.Fatalf("commit changed: %d, want 1", result.CommittedIndex)
793				}
794				if out.FinalTerm != 2 || out.FinalCommittedIndex != 1 {
795					t.Fatalf("final state changed: term=%d ci=%d", out.FinalTerm, out.FinalCommittedIndex)
796				}
797				if !reflect.DeepEqual(out.FinalLog, original) {
798					t.Fatalf("log changed: %+v", out.FinalLog)
799				}
800				// 输出约定：该拒绝的 JSON 中不出现 conflict 键。
801				encoded, err := json.Marshal(result)
802				if err != nil {
803					t.Fatal(err)
804				}
805				if strings.Contains(string(encoded), "conflict") {
806					t.Fatalf("rejection JSON must omit conflict: %s", encoded)
807				}
808			})
809		}
810	}
